-- Dema's commission sheet ("Dema $$.xlsx") at Granite Depot of Indianapolis:
-- every row of its 2026 tab, and the paid rows of its 2025 tab (the unpaid
-- ones were carried into 2026). One row per sale, bonus or payment, on the
-- payroll date the sheet paid it; payroll dates already gone by are paid out.
-- Ten unpaid sales are tied to the quote Dema sold for them here (same name
-- and total), with the sheet's amounts kept as the admin's own, so the
-- sync fills in payment and install instead of adding the sale twice.
INSERT INTO quote_commissions
  (company_id, quote_id, user_id, customer_id, customer_label, quote_total, total_override,
   commission_amount, commission_override, parts_json, status, payroll_date, paid_out_at, signed_at)
